import React, { useState, useMemo } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceArea, Label } from 'recharts';
import { Users, Pill, Activity, ArrowLeft, AlertCircle, Calendar, ChevronDown, Search } from 'lucide-react';
import './index.css';

// --- 固定數據 ---
const admissionHistory = [
  { id: 'ADM-001', date: '2026/09/10 - 09/30 (本次住院)' },
  { id: 'ADM-002', date: '2025/11/12 - 11/28' }
];

const fullData = Array.from({ length: 21 }, (_, i) => {
  const day = 10 + i;
  return {
    date: '09/' + day,
    na: 142 - (i * 0.8) + Math.sin(i),
    k: 3.6 + (i * 0.12),
    index: i
  };
});

const medData = [
  { name: 'FUROSEMIDE (LASIX)', type: 'Na+ Impact', startIdx: 0, endIdx: 15, color: '#3B82F6', impact: '138 -> 128', level: '高度相關' },
  { name: 'LISINOPRIL', type: 'K+ Impact', startIdx: 5, endIdx: 12, color: '#EF4444', impact: '3.5 -> 5.5', level: '中度相關' },
  { name: 'ASPIRIN', type: 'Anti-platelet', startIdx: 0, endIdx: 25, color: '#94A3B8', impact: 'N/A', level: '無明顯相關' }
];

const medicationLogs = [
  { name: 'FUROSEMIDE (LASIX)', start: '09/10 08:00', end: '使用中', dose: ['40 mg IV q12h', '20 mg IV q12h (09/18 減量)'], status: 'ACTIVE' },
  { name: 'LISINOPRIL', start: '09/12 09:00', end: '09/18 10:00', dose: ['5 mg PO QD'], status: 'PAST' },
  { name: 'SPIRONOLACTONE', start: '09/15 08:00', end: '使用中', dose: ['25 mg PO QD'], status: 'ACTIVE' }
];

const mockPatients = [
  {id:'P001', name:'王小明', info:'(男/68)', na:'128', k:'4.5', room:'802-1', status:'危急'}, 
  {id:'P002', name:'李大同', info:'(男/72)', na:'138', k:'4.2', room:'805-2', status:'觀察中'}
];

export default function App() {
  const [view, setView] = useState('overview');
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [windowSize, setWindowSize] = useState(7);
  const [startIndex, setStartIndex] = useState(0);

  const visibleData = useMemo(() => fullData.slice(startIndex, startIndex + windowSize), [startIndex, windowSize]);

  // --- 1. 藥物查詢頁面 ---
  if (view === 'repository') {
    return (
      <div className="flex h-screen bg-[#F8FAFC] font-sans text-left">
        <div className="w-64 bg-white border-r p-6 flex flex-col shadow-sm">
          <div className="flex items-center gap-2 text-blue-600 font-bold mb-10 text-xl italic"><Activity /> ADR PRO</div>
          <button onClick={() => setView('overview')} className="flex items-center gap-3 p-4 text-slate-400 hover:bg-slate-50 rounded-2xl font-bold w-full mb-4 transition-all"><Users size={18} /> 病人總覽</button>
          <button className="flex items-center gap-3 p-4 bg-blue-600 text-white rounded-2xl font-bold w-full shadow-lg"><Pill size={18} /> 藥物查詢</button>
        </div>
        <div className="flex-1 p-16 text-center overflow-y-auto">
          <div className="max-w-4xl mx-auto">
            <h1 className="text-4xl font-black italic text-slate-800 mb-10 border-b-4 border-blue-600 inline-block px-4 tracking-tighter uppercase">Lexidrug Repository</h1>
            <div className="relative mb-12 shadow-xl rounded-full border bg-white overflow-hidden">
              <Search className="absolute left-8 top-6 text-slate-300" size={24} />
              <input className="w-full p-7 pl-20 outline-none text-xl" placeholder="Search Global Database..." />
            </div>
          </div>
        </div>
      </div>
    );
  }

  // --- 2. 臨床儀表板 (圖表與甘特圖) ---
  if (view === 'dashboard') {
    return (
      <div className="flex h-screen bg-[#F8FAFC] font-sans text-left">
        <div className="w-64 bg-white border-r p-6 flex flex-col shadow-sm">
          <div className="flex items-center gap-2 text-blue-600 font-bold mb-10 text-xl italic"><Activity /> ADR PRO</div>
          <button onClick={() => setView('overview')} className="flex items-center gap-3 p-4 bg-blue-600 text-white rounded-2xl font-bold shadow-lg w-full mb-4"><Users size={18} /> 病人總覽</button>
          <button onClick={() => setView('repository')} className="flex items-center gap-3 p-4 text-slate-400 hover:bg-slate-50 rounded-2xl font-bold w-full"><Pill size={18} /> 藥物查詢</button>
        </div>

        <div className="flex-1 overflow-y-auto p-8">
          <div className="flex justify-between items-center mb-8">
            <div className="flex items-center gap-4">
              <button onClick={() => setView('overview')} className="p-3 bg-white border rounded-xl hover:text-blue-600 shadow-sm transition-all"><ArrowLeft size={18} /></button>
              <div className="bg-white px-6 py-3 rounded-2xl border flex items-center gap-3 shadow-sm font-bold text-slate-700 text-sm italic">
                {admissionHistory[0].date} <ChevronDown size={14} className="text-slate-300" />
              </div>
            </div>
            <div className="flex gap-2">
              {[3, 7, 14].map(d => (
                <button key={d} onClick={() => { setWindowSize(d); setStartIndex(0); }} className={windowSize === d ? "px-6 py-2 rounded-lg bg-blue-600 text-white font-bold text-xs" : "px-6 py-2 bg-white text-slate-400 border font-bold text-xs"}>{d}D</button>
              ))}
            </div>
          </div>

          {/* 圖表與連動滑桿 */}
          <div className="bg-white rounded-[2.5rem] p-10 border border-slate-100 shadow-sm mb-8">
            <div className="h-72 w-full mb-6">
              <ResponsiveContainer>
                <LineChart data={visibleData} margin={{ left: 10, right: 10 }}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                  <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fill: '#94A3B8', fontSize: 11}} />
                  <YAxis yAxisId="na" domain={[120, 160]} ticks={[120, 130, 140, 150, 160]} axisLine={false} tickLine={false} tick={{fill: '#F97316', fontSize: 10}} width={40} />
                  <YAxis yAxisId="k" orientation="right" domain={[2, 8]} ticks={[2, 4, 6, 8]} axisLine={false} tickLine={false} tick={{fill: '#6366F1', fontSize: 10}} width={40} />
                  <Tooltip contentStyle={{ borderRadius: '15px', border: 'none', boxShadow: '0 10px 20px rgba(0,0,0,0.05)' }} />

                  <ReferenceArea yAxisId="na" y1={135} y2={145} fill="#F97316" fillOpacity={0.05}>
                    <Label value="Na Range" position="insideTopLeft" fill="#F97316" fontSize={9} />
                  </ReferenceArea>
                  <ReferenceArea yAxisId="k" y1={3.5} y2={5.0} fill="#6366F1" fillOpacity={0.05}>
                    <Label value="K Range" position="insideBottomRight" fill="#6366F1" fontSize={9} />
                  </ReferenceArea>

                  <Line yAxisId="na" type="monotone" dataKey="na" stroke="#F97316" strokeWidth={5} dot={{r: 6, fill: '#F97316', strokeWidth: 3, stroke: '#fff'}} animationDuration={0} />
                  <Line yAxisId="k" type="monotone" dataKey="k" stroke="#6366F1" strokeWidth={5} dot={{r: 6, fill: '#6366F1', strokeWidth: 3, stroke: '#fff'}} animationDuration={0} />
                </LineChart>
              </ResponsiveContainer>
            </div>

            <div className="px-10 mb-12">
              <input type="range" min="0" max={21 - windowSize} value={startIndex} onChange={(e) => setStartIndex(parseInt(e.target.value))} className="w-full h-2 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-blue-600" />
              <div className="flex justify-between text-[10px] font-black text-slate-300 mt-4 uppercase">
                <span>住院開始 (09/10)</span>
                <span className="text-blue-600 font-bold bg-blue-50 px-4 py-1 rounded-full border border-blue-100 italic tracking-tight">平移檢視: {visibleData[0].date} - {visibleData[windowSize-1].date}</span>
                <span>住院結束 (09/30)</span>
              </div>
            </div>

            <div className="space-y-4 pt-10 border-t">
              {medData.map((med, i) => {
                const viewStart = startIndex;
                const viewEnd = startIndex + windowSize - 1;
                const left = Math.max(0, ((med.startIdx - viewStart) / windowSize) * 100);
                const right = Math.min(100, ((med.endIdx - viewStart + 1) / windowSize) * 100);
                const width = Math.max(0, right - left);

                return (
                  <div key={i} className="flex items-center">
                    <div className="w-44 pr-4 text-left">
                      <p className="text-[11px] font-black text-slate-700 italic tracking-tighter">{med.name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">{med.type} 關聯</p>
                    </div>
                    <div className="flex-1 h-8 bg-slate-50 rounded-xl relative overflow-hidden border border-slate-100">
                      {width > 0 && (
                        <div className="absolute h-full transition-all duration-100 opacity-80 rounded-lg shadow-sm flex items-center px-4" style={{ left: left + '%', width: width + '%', backgroundColor: med.color }}>
                          <span className="text-[8px] text-white font-black uppercase opacity-60">Usage</span>
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* 實際用藥明細 */}
          <div className="bg-white rounded-[2.5rem] shadow-sm border p-10 mb-8 text-left">
             <div className="flex items-center gap-2 mb-8 font-black text-slate-700 italic border-l-4 border-blue-600 pl-4 uppercase">實際用藥全紀錄 (住院詳細明細)</div>
             <table className="w-full text-left text-xs">
                <thead className="text-slate-400 border-b">
                  <tr><th className="pb-4">藥物名稱</th><th className="pb-4">開始給藥</th><th className="pb-4">停止給藥</th><th className="pb-4">劑量變動歷程</th><th className="pb-4 text-right">狀態</th></tr>
                </thead>
                <tbody className="divide-y">
                  {medicationLogs.map((log, i) => (
                    <tr key={i} className="hover:bg-slate-50 transition-all">
                      <td className="py-6 font-black italic text-slate-700">{log.name}</td>
                      <td className="py-6 text-slate-400">{log.start}</td>
                      <td className="py-6 text-slate-400">{log.end}</td>
                      <td className="py-6 font-bold text-slate-600">{log.dose.map((d, di) => <div key={di} className="flex items-center gap-2"><div className="w-1.5 h-1.5 rounded-full bg-blue-500"></div>{d}</div>)}</td>
                      <td className="py-6 text-right font-black uppercase text-[10px]"><span className={log.status === 'ACTIVE' ? "text-green-500" : "text-slate-300"}>{log.status}</span></td>
                    </tr>
                  ))}
                </tbody>
             </table>
          </div>

          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden mb-12 text-left">
            <div className="bg-rose-50/50 p-8 border-b flex items-center gap-3"><AlertCircle className="text-rose-500" size={24} /><h2 className="text-rose-900 font-black italic text-xl uppercase tracking-tighter">ADR 關聯分析結果</h2></div>
            <table className="w-full text-left text-sm">
              <thead className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase tracking-widest">
                <tr><th className="p-8">臨床肇因藥物</th><th className="p-8">離子</th><th className="p-8 text-center">時序檢驗值變化</th><th className="p-8 text-right">智慧判定結論</th></tr>
              </thead>
              <tbody className="divide-y">
                {medData.map((med, i) => (
                  <tr key={i} className="hover:bg-slate-50 transition-all">
                    <td className="p-8 font-black text-slate-700 italic">{med.name} {med.level.includes('高') && <span className="bg-rose-100 text-rose-500 text-[8px] px-2 py-0.5 rounded font-black ml-2 uppercase">Critical</span>}</td>
                    <td className="p-8 text-slate-400 font-bold uppercase">{med.type}</td>
                    <td className="p-8 font-mono font-black text-2xl italic text-center text-rose-500">{med.impact}</td>
                    <td className="p-8 text-right font-black"><span className="px-10 py-4 rounded-3xl text-xs font-black uppercase text-white shadow-xl inline-block" style={{ backgroundColor: med.level.includes('高') ? '#F43F5E' : med.level.includes('中') ? '#F97316' : '#94A3B8' }}>{med.level}</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  }

  // --- 3. 首頁：病人清單 (完美對齊截圖版) ---
  return (
    <div className="flex h-screen bg-[#F8FAFC] font-sans text-left">
      {/* 左側導覽列 */}
      <div className="w-64 bg-white border-r p-6 flex flex-col shadow-sm">
        <div className="flex items-center gap-2 text-blue-600 font-bold mb-10 text-xl italic tracking-tighter"><Activity strokeWidth={3}/> ADR PRO</div>
        <button className="flex items-center gap-3 p-4 bg-blue-600 text-white rounded-2xl font-bold shadow-lg shadow-blue-100 mb-4 transition-all"><Users size={18} /> 病人總覽</button>
        <button onClick={() => setView('repository')} className="flex items-center gap-3 p-4 text-slate-400 hover:bg-slate-50 rounded-2xl font-bold transition-all"><Pill size={18} /> 藥物查詢</button>
      </div>

      {/* 右側滿版內容區 */}
      <div className="flex-1 p-12 overflow-y-auto">
        {/* 標題設計對齊截圖：深色斜體 + 底部藍色粗線 */}
        <h1 className="text-2xl font-black italic text-slate-800 mb-8 border-b-[3px] border-blue-600 inline-block pb-1 uppercase tracking-tight">
          Patient Admission Records
        </h1>

        {/* 表格卡片 */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden max-w-6xl">
          <table className="w-full text-left">
            <thead className="bg-white border-b border-slate-100 text-slate-400 text-[11px] font-bold uppercase tracking-widest">
              <tr>
                <th className="py-6 px-8">病歷 ID</th>
                <th className="py-6 px-8">病患</th>
                <th className="py-6 px-8 text-center">目前房號</th>
                <th className="py-6 px-8 text-center">最新 Na+ / K+</th>
                <th className="py-6 px-8 text-right pr-12">監測狀態</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {mockPatients.map(p => (
                <tr key={p.id} onClick={() => { setSelectedPatient(p); setView('dashboard'); }} className="hover:bg-slate-50 transition-all cursor-pointer group">
                  {/* 病歷 ID: 藍色粗體 */}
                  <td className="py-6 px-8 font-black text-blue-600 text-sm tracking-tight">{p.id}</td>

                  {/* 病患: 姓名 + 灰色小字性別年齡 */}
                  <td className="py-6 px-8 text-slate-700 font-bold text-sm">
                    {p.name} <span className="text-slate-400 font-normal ml-1">{p.info}</span>
                  </td>

                  {/* 房號: 灰色 */}
                  <td className="py-6 px-8 text-slate-500 font-medium text-sm text-center">{p.room}</td>

                  {/* 最新 Na/K: 紅色底線 + 黑色 */}
                  <td className="py-6 px-8 font-sans font-bold text-base text-center">
                    <span className={p.status === '危急' ? "text-rose-500 underline decoration-rose-500 underline-offset-4 font-black" : "text-slate-700 font-black"}>
                      {p.na}
                    </span> 
                    <span className="text-slate-400 font-normal mx-1">/</span> 
                    <span className="text-slate-700 font-black">{p.k}</span>
                  </td>

                  {/* 狀態: 紅色或黃色藥丸樣式按鈕 */}
                  <td className="py-6 px-8 text-right pr-12">
                    <span className={
                      p.status === '危急' 
                        ? "bg-rose-100 text-rose-500 px-4 py-1.5 rounded-full text-[11px] font-bold tracking-widest border border-rose-50" 
                        : "bg-[#FEF3C7] text-[#D97706] px-4 py-1.5 rounded-full text-[11px] font-bold tracking-widest border border-yellow-50"
                    }>
                      {p.status}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
